  <String, Object?>{'name': '绳索侧卷腹', 'group': '核心', 'kind': '力量', 'equipment': '绳索', 'pattern': '卷腹', 'difficulty': 2, 'aliases': <String>['cable side crunch'], 'emphasis': <String>['abs'], 'cue': '将电缆手柄连接到低滑轮上并站在机器旁边。 用距离机器最远的手抓住手柄，并将另一只手放在臀部上。 双脚分开与肩同宽，膝盖稍微弯曲。 收紧腹肌，腰部向侧面弯曲，将肘部向下拉向臀部。 在底部停顿片刻，然后慢慢回到起始位置。 重复所需的重复次数，然后换边。', 'met': 0.0, 'imageSlug': 'zh_0223'},
