  <String, Object?>{'name': '绳索蹲姿弯举', 'group': '手臂', 'kind': '力量', 'equipment': '绳索', 'pattern': '深蹲', 'difficulty': 2, 'aliases': <String>['cable squatting curl'], 'emphasis': <String>['biceps'], 'cue': '将电缆手柄连接到电缆机器上的最低设置。 面向机器站立，双脚分开与肩同宽。 反手握住电缆手柄，手掌朝上，手臂完全伸展。 将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。 当你蹲下时，将电缆手柄卷向肩膀，保持肘部靠近身体两侧。 在弯举的顶部暂停片刻，挤压二头肌。 慢慢地将电缆手柄放回起始位置，完全伸展双臂。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_1644'},
