  <String, Object?>{'name': '绳索蜷身反向卷腹', 'group': '核心', 'kind': '力量', 'equipment': '绳索', 'pattern': '卷腹', 'difficulty': 2, 'aliases': <String>['cable tuck reverse crunch'], 'emphasis': <String>['abs'], 'cue': '将电缆连接到低滑轮上，然后面朝上躺在垫子上。 用双手握住电缆并将双臂伸直至胸部上方。 弯曲膝盖并抬起双腿，使膝盖靠近胸部。 同时，将骨盆向胸部弯曲，将臀部抬离地面。 在顶部暂停片刻，然后慢慢降低双腿和臀部回到起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_0242'},
