  <String, Object?>{'name': '哑铃上斜扩胸', 'group': '胸', 'kind': '力量', 'equipment': '哑铃', 'pattern': '综合', 'difficulty': 2, 'aliases': <String>['dumbbell incline breeding'], 'emphasis': <String>['pectorals'], 'cue': '设置一个 45 度角的上斜凳。 坐在长凳上，背部靠在垫子上，双脚平放在地面上。 双手各握一个哑铃，正手握握，手掌朝前。 首先，双臂完全伸展，垂直于地面。 慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。 在底部暂停片刻，然后将哑铃推回到起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_0316'},
