  <String, Object?>{'name': '哑铃上斜单臂飞鸟', 'group': '胸', 'kind': '力量', 'equipment': '哑铃', 'pattern': '上斜推', 'difficulty': 2, 'aliases': <String>['dumbbell incline one arm fly'], 'emphasis': <String>['pectorals'], 'cue': '将倾斜凳调整至 30-45 度角。 坐在长凳上，一只手拿着哑铃，将其放在大腿上。 向后躺在长凳上，双脚平放在地面上。 握住哑铃，手臂伸直越过胸部。 将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。 当手臂与地面平行时暂停，然后反向运动，使哑铃回到起始位置。 重复所需的重复次数，然后换臂。', 'met': 0.0, 'imageSlug': 'zh_1279'},
