  <String, Object?>{'name': '哑铃单臂肩推', 'group': '肩', 'kind': '力量', 'equipment': '哑铃', 'pattern': '垂直推', 'difficulty': 2, 'aliases': <String>['dumbbell one arm shoulder press'], 'emphasis': <String>['delts'], 'cue': '双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。 向上推哑铃，直到手臂完全伸过头顶。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。', 'met': 0.0, 'imageSlug': 'zh_0361'},
