  <String, Object?>{'name': '哑铃后侧平举', 'group': '肩', 'kind': '力量', 'equipment': '哑铃', 'pattern': '平举', 'difficulty': 2, 'aliases': <String>['dumbbell rear lateral raise'], 'emphasis': <String>['delts'], 'cue': '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心参与。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_0380'},
