  <String, Object?>{'name': '哑铃坐姿交替前平举', 'group': '肩', 'kind': '力量', 'equipment': '哑铃', 'pattern': '平举', 'difficulty': 2, 'aliases': <String>['dumbbell seated alternate front raise'], 'emphasis': <String>['delts'], 'cue': '坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个哑铃，手掌朝向身体，手臂向下伸展到身体两侧。 保持双臂伸直，将一只哑铃举至身前，直至其与地面平行。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 用另一只手臂重复上述步骤。 双臂交替进行所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_0387'},
