  <String, Object?>{'name': '哑铃站姿肱二头肌弯举', 'group': '手臂', 'kind': '力量', 'equipment': '哑铃', 'pattern': '弯举', 'difficulty': 2, 'aliases': <String>['dumbbell standing biceps curl'], 'emphasis': <String>['biceps'], 'cue': '站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_0416'},
