  <String, Object?>{'name': '反向腿弯举(在引体向上绳索器械)', 'group': '腿', 'kind': '力量', 'equipment': '自重', 'pattern': '弯举', 'difficulty': 2, 'aliases': <String>['inverse leg curl (on pull-up cable machine)'], 'emphasis': <String>['hamstrings'], 'cue': '调整缆绳机，使踝带处于最低设置。 面朝下躺在长凳上，双腿伸展，脚踝带固定在脚上。 握住长凳的把手以保持稳定。 弯曲膝盖，将双腿向臀部弯曲，挤压腿筋。 在动作的最高点暂停片刻，然后慢慢将双腿放回起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_2400'},
