  <String, Object?>{'name': '开合波比跳', 'group': '有氧', 'kind': '有氧', 'equipment': '自重', 'pattern': '综合', 'difficulty': 2, 'aliases': <String>['jack burpee'], 'emphasis': <String>['cardiovascular system'], 'cue': '从站立位置开始，双脚分开与肩同宽。 将身体降低至蹲姿，将双手放在身前的地面上。 双脚向后踢，以俯卧撑姿势落地。 进行俯卧撑，将胸部降低到地面，然后再向上推。 双脚向前跳，以蹲姿落地。 爆发性地跳起，将双臂举过头顶。 轻轻落地并立即回到蹲姿，开始下一次重复。', 'met': 6.5, 'imageSlug': 'zh_0501'},
