  <String, Object?>{'name': '杠杆机大锤握牧师凳弯举', 'group': '手臂', 'kind': '力量', 'equipment': '器械', 'pattern': '弯举', 'difficulty': 2, 'aliases': <String>['lever hammer grip preacher curl'], 'emphasis': <String>['biceps'], 'cue': '调整座椅高度并将自己放在杠杆机上。 将你的上臂放在讲道垫上，确保你的胸部压在上面。 用锤子握把抓住手柄（手掌相对）。 保持上臂静止，呼气并将手柄卷向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气并慢慢将手柄放回起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_1615'},
