  <String, Object?>{'name': '马桶式深蹲', 'group': '核心', 'kind': '力量', 'equipment': '自重', 'pattern': '深蹲', 'difficulty': 2, 'aliases': <String>['potty squat'], 'emphasis': <String>['abs'], 'cue': '双脚分开与肩同宽站立，脚趾稍微向外。 弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。 在整个动作过程中保持挺胸、背部挺直。 降低自己，直到大腿与地面平行或尽可能低。 在底部停顿片刻，然后推动脚后跟回到起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_3119'},
