  <String, Object?>{'name': '雪橇机45°腿举(侧面视角)', 'group': '腿', 'kind': '力量', 'equipment': '雪橇机', 'pattern': '深蹲', 'difficulty': 2, 'aliases': <String>['sled 45° leg press (side pov)'], 'emphasis': <String>['glutes'], 'cue': '调整雪橇机的座椅，使双脚放在踏板上时膝盖呈90度角。 坐在雪橇机上，背部平放在靠背上，双脚与肩同宽放在踏板上。 握住座椅两侧的把手以保持稳定性。 推动脚踏板以伸展双腿，将其完全伸直。 在顶部停顿片刻，然后慢慢弯曲膝盖，将踏板放回起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_1463'},
