  <String, Object?>{'name': '雪橇机小腿推举在腿举', 'group': '小腿', 'kind': '力量', 'equipment': '雪橇机', 'pattern': '深蹲', 'difficulty': 2, 'aliases': <String>['sled calf press on leg press'], 'emphasis': <String>['calves'], 'cue': '调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。 将双脚与肩同宽放在雪橇上，脚趾指向前方。 松开安全手柄，并通过伸展膝盖和脚踝将雪橇推离您。 在动作的最高点暂停片刻，然后弯曲膝盖和脚踝，慢慢将雪橇放回原处。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_1391'},
