  <String, Object?>{'name': '咒术师', 'group': '核心', 'kind': '力量', 'equipment': '哑铃', 'pattern': '综合', 'difficulty': 2, 'aliases': <String>['spell caster'], 'emphasis': <String>['abs'], 'cue': '双脚分开与肩同宽站立，一只手握住哑铃。 稍微弯曲膝盖，腰部向前转动，保持背部挺直。 将哑铃伸向另一只脚的手臂，同时旋转躯干。 返回起始位置并在另一侧重复。 继续交替进行所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_0777'},
