  <String, Object?>{'name': '脊柱拉伸', 'group': '背', 'kind': '柔韧', 'equipment': '自重', 'pattern': '综合', 'difficulty': 2, 'aliases': <String>['spine stretch'], 'emphasis': <String>['spine'], 'cue': '坐在地上，双腿在身前伸展。 将双手放在身后的地面上，手指指向身体。 启动你的核心并慢慢向后倾斜，保持背部挺直。 继续向后倾斜，直到感觉到脊柱被拉伸。 保持伸展几秒钟，然后慢慢回到起始位置。 重复所需的重复次数。', 'met': 0.0, 'imageSlug': 'zh_1363'},
